def transform(grid):
    g = np.array(grid).copy()
    bg = background(g)
    H, W = g.shape
    d = dividers(g)
    rows = [y for y, c in d["rows"] if c != bg]
    cols = [x for x, c in d["cols"] if c != bg]
    if cols:
        line_col = g[0, cols[0]]
        dirs = [(0, -1), (0, 1)]
    else:
        line_col = g[rows[0], 0]
        dirs = [(-1, 0), (1, 0)]
    dots = [(y, x) for y in range(H) for x in range(W)
            if g[y, x] != bg and g[y, x] != line_col]
    for (y, x) in dots:
        dc = g[y, x]
        for dy, dx in dirs:
            cy, cx = y + dy, x + dx
            path = []
            hit = None
            while 0 <= cy < H and 0 <= cx < W:
                if g[cy, cx] == line_col and ((cols and cx in cols) or (rows and cy in rows)):
                    hit = (cy, cx)
                    break
                path.append((cy, cx))
                cy += dy; cx += dx
            if hit is None:
                continue
            for py, px in path:
                g[py, px] = dc
            hy, hx = hit
            for yy in range(hy - 1, hy + 2):
                for xx in range(hx - 1, hx + 2):
                    if 0 <= yy < H and 0 <= xx < W:
                        g[yy, xx] = line_col
            g[hy, hx] = dc
        emit(g, f"Dot at ({y},{x}) fires rays perpendicular to the lines up to the nearest line on each side; each hit cell becomes {dc} framed by a 3x3 ring of {line_col}.")
    emit(g, "All dots processed: final grid.")
    return g
